pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        c.initialize();
        address newOwner = address(0x123);
        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.transferOwnership.selector, newOwner));
        assertTrue(ok);
    }
}
